const item = $input.first().json;
const prev = $('Normalize').first().json;

const raw = item.choices[0].message.content || '';

if (!raw || raw.trim() === '') {
  throw new Error('OpenAI returned empty content');
}

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  throw new Error('Failed to parse response: ' + raw.substring(0, 500));
}

const validCategories = ['Bug Report', 'Feature Request', 'Billing Issue', 'Technical Question', 'Incident/Outage'];
const validPriorities = ['Low', 'Medium', 'High'];

const category = validCategories.includes(parsed.category) ? parsed.category : 'Technical Question';
const priority = validPriorities.includes(parsed.priority) ? parsed.priority : 'Medium';
let confidence = parseFloat(parsed.confidence);
if (isNaN(confidence)) confidence = 0.5;
confidence = Math.max(0, Math.min(1, confidence));
confidence = Math.round(confidence * 100) / 100;

const entities = parsed.entities || {};
const defaultEntities = {
  account_ids: entities.account_ids || [],
  invoice_numbers: entities.invoice_numbers || [],
  error_codes: entities.error_codes || [],
  amounts: entities.amounts || [],
  excess_amount: entities.excess_amount || null,
  products_or_systems: entities.products_or_systems || [],
  timeframe: entities.timeframe || ''
};

return [{
  json: {
    id: prev.id,
    source: prev.source,
    raw_message: prev.raw_message,
    received_at: prev.received_at,
    category: category,
    priority: priority,
    confidence: confidence,
    core_issue: parsed.core_issue || '',
    entities: defaultEntities,
    urgency_signal: parsed.urgency_signal || '',
    summary: parsed.summary || '',
    raw_model_output: raw
  }
}];

const item = $input.first().json;

const routeMap = {
  'Bug Report': 'Engineering',
  'Incident/Outage': 'Engineering',
  'Feature Request': 'Product',
  'Billing Issue': 'Billing',
  'Technical Question': 'IT/Security'
};

const queue_attempted = routeMap[item.category] || 'Human Review';

let escalate = false;
const reasons = [];

if (item.confidence < 0.70) {
  escalate = true;
  reasons.push('Confidence ' + item.confidence + ' < 0.70');
}

const incidentPatterns = /outage|down for all users|multiple users affected|stopped loading/i;
if (item.category === 'Incident/Outage' || incidentPatterns.test(item.raw_message)) {
  escalate = true;
  reasons.push('Incident signal detected');
}

if (item.category === 'Billing Issue') {
  const amounts = (item.entities.amounts || [])
    .map(a => parseFloat(String(a).replace(/[^0-9.\-]/g, '')))
    .filter(a => !isNaN(a));
  if (amounts.length >= 2) {
    const discrepancy = Math.abs(amounts[0] - amounts[1]);
    if (discrepancy > 500) {
      escalate = true;
      reasons.push('Billing discrepancy $' + discrepancy + ' > $500');
    }
  }
}

// Rule 3b — explicit overcharge stated
if (item.category === 'Billing Issue' && item.entities.excess_amount) {
  const excess = parseFloat(String(item.entities.excess_amount).replace(/[^0-9.\-]/g, ''));
  if (!isNaN(excess) && excess > 500) {
    escalate = true;
    reasons.push('Stated overcharge $' + excess + ' > $500');
  }
}

const queue = escalate ? 'Human Review' : queue_attempted;
const escalation_reason = reasons.length > 0 ? reasons.join('; ') : '';
const processed_at = new Date().toISOString();
const entities_json = JSON.stringify(item.entities);

return [{
  json: {
    id: item.id,
    source: item.source,
    category: item.category,
    priority: item.priority,
    confidence: item.confidence,
    core_issue: item.core_issue,
    entities_json: entities_json,
    urgency_signal: item.urgency_signal,
    queue: queue,
    queue_attempted: queue_attempted,
    escalate: escalate,
    escalation_reason: escalation_reason,
    summary: item.summary,
    raw_message: item.raw_message,
    processed_at: processed_at
  }
}];
